// Deterministic EDGE-CASE media for the P12 hardening check: the odd, hostile, and unusual inputs a real
// editing engine meets (VFR phones, rotation tags, 4K, 120 fps, anamorphic SAR, interlaced, 5.1, odd sizes,
// sub-second clips, non-zero start times, still images, every container, a 25-minute marathon).
// Same pattern as fixtures.mjs: generated by ffmpeg into ~/.cache/pi-motion-studio/fixtures/edge (outside
// git), built once, checksummed in edge/manifest.json, deterministic (-fflags +bitexact), offline afterwards.
//   engine/verify/hardening.mjs builds + uses these; `studio cache gc --fixtures` may remove them on demand.
import { createHash } from 'node:crypto';
import { createReadStream, existsSync, mkdirSync, rmSync, statSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { BARCODE, barcodeSource } from './lib/barcode.mjs';
import { readJson, writeJson } from './lib/film.mjs';
import { run } from './lib/proc.mjs';

export const EDGE_DIR = join(homedir(), '.cache', 'pi-motion-studio', 'fixtures', 'edge');
const MANIFEST = join(EDGE_DIR, 'manifest.json');
const RECIPE = 1; // bump to invalidate every edge fixture when a recipe changes

const BEEP = (dur, rate, period = 2) => `aevalsrc=exprs='0.7*sin(2*PI*1000*t)*lt(mod(t,${period}),0.05)':s=${rate}:d=${dur}`;
const ENC = ['-fflags', '+bitexact', '-flags:v', '+bitexact', '-flags:a', '+bitexact'];
const libx264 = (crf = 18, { preset = 'medium', pix = 'yuv420p', extra = [] } = {}) => ['-c:v', 'libx264', '-preset', preset, '-crf', String(crf), '-pix_fmt', pix, '-threads', '4', ...extra];
const ff = (args) => run('ffmpeg', ['-y', '-v', 'error', '-nostdin', ...args]);

// base frame content: testsrc2 + the frame-index barcode strip at (0,0). The caller finishes the chain with
// `,format=…[v]` (and any transform before it), so the same helper serves every size and codec path.
// NOTE: testsrc2 silently rounds odd sizes to even — build the content at 2x and `scale=` down for odd frames.
const strip = ({ w, h, fps, dur, cell = BARCODE.cell }) => ({
  v: ['-f', 'lavfi', '-i', `testsrc2=s=${w}x${h}:r=${fps}:d=${dur}`, '-f', 'lavfi', '-i', barcodeSource(fps, dur, { bits: BARCODE.bits, cell })],
  base: '[0:v][1:v]overlay=0:0', cell,
});

// 6 sines, one per 5.1 channel, so the downmix is measurable per channel (a silent center would be untestable)
const SINES_51 = '0.5*sin(2*PI*100*t)|0.5*sin(2*PI*203*t)|0.5*sin(2*PI*307*t)|0.5*sin(2*PI*409*t)|0.5*sin(2*PI*503*t)|0.5*sin(2*PI*601*t)';

export const EDGE_FIXTURES = {
  // portrait phone: upright 1080x1920 content, VFR (every 3rd frame dropped), stored landscape + rotate tag, 48 kHz stereo
  'edge-vfr-phone': { file: 'edge-vfr-phone.mp4', desc: '10 s portrait phone clip: 1080x1920 upright, VFR (every 3rd frame dropped), rotate tag, 48 kHz stereo', async build(out, dir) {
    const s = strip({ w: 1080, h: 1920, fps: 30, dur: 10 }), tmp = join(dir, '.edge-vfr-src.mp4');
    await ff([...s.v, '-f', 'lavfi', '-i', BEEP(10, 48000),
      '-filter_complex', `${s.base},select='not(eq(mod(n,3),2))',transpose=2,format=yuv420p[v]`, '-map', '[v]', '-map', '2:a',
      ...libx264(18, { preset: 'veryfast' }), '-fps_mode', 'vfr', '-c:a', 'aac', '-b:a', '128k', '-ac', '2', ...ENC, tmp]);
    await ff(['-display_rotation:v:0', '-90', '-i', tmp, '-c', 'copy', ...ENC, out]);
    rmSync(tmp, { force: true });
  } },
  // rotate=180: upright content stored head-over-heels + the 180 tag (players and ingest must flip it back)
  'edge-rot-180': { file: 'edge-rot-180.mp4', desc: '6 s 720x480 stored rotated 180 + rotate tag 180, 48 kHz stereo', async build(out, dir) {
    const s = strip({ w: 720, h: 480, fps: 30, dur: 6 }), tmp = join(dir, '.edge-rot180-src.mp4');
    await ff([...s.v, '-f', 'lavfi', '-i', BEEP(6, 48000),
      '-filter_complex', `${s.base},transpose=1,transpose=1,format=yuv420p[v]`, '-map', '[v]', '-map', '2:a',
      ...libx264(18), '-c:a', 'aac', '-b:a', '96k', '-ac', '2', ...ENC, tmp]);
    await ff(['-display_rotation:v:0', '180', '-i', tmp, '-c', 'copy', ...ENC, out]);
    rmSync(tmp, { force: true });
  } },
  // odd sizes: 854x480 (even but non-square-pixel-friendly odd width) and a genuinely odd 123x77 at 12 fps.
  // 420 encoders cannot carry odd dimensions (ffmpeg crops), so the tiny one is yuv444p — the honest way odd
  // sizes exist in the wild. Content built at 246x154 (testsrc2 rounds to even) then scaled to 123x77.
  'edge-odd-854': { file: 'edge-odd-854.mp4', extra: ['edge-odd-123.mp4'], desc: '6 s 854x480@30 + a 6 s 123x77@12 yuv444p (odd dims, cell-7 barcode), both with audio', async build(out, dir) {
    const a = strip({ w: 854, h: 480, fps: 30, dur: 6, cell: 16 });
    await ff([...a.v, '-f', 'lavfi', '-i', BEEP(6, 48000), '-filter_complex', `${a.base},format=yuv420p[v]`, '-map', '[v]', '-map', '2:a',
      ...libx264(18), '-c:a', 'aac', '-b:a', '96k', '-ac', '2', ...ENC, out]);
    const b = strip({ w: 246, h: 154, fps: 12, dur: 6, cell: 7 });
    await ff([...b.v, '-f', 'lavfi', '-i', BEEP(6, 48000), '-filter_complex', `[0:v]scale=123:77[base];[base][1:v]overlay=0:0,format=yuv444p[v]`, '-map', '[v]', '-map', '2:a',
      ...libx264(14, { pix: 'yuv444p' }), '-c:a', 'aac', '-b:a', '96k', '-ac', '2', ...ENC, join(dir, 'edge-odd-123.mp4')]);
  } },
  // anamorphic: 960x540 stored, SAR 2:1 -> display 1920x540. The conform must land at 1920x540 with SAR 1:1.
  'edge-sar': { file: 'edge-sar.mp4', desc: '6 s anamorphic 960x540 SAR 2:1 (display 1920x540), 48 kHz stereo', async build(out) {
    const s = strip({ w: 960, h: 540, fps: 30, dur: 6, cell: 20 });
    await ff([...s.v, '-f', 'lavfi', '-i', BEEP(6, 48000), '-filter_complex', `${s.base},setsar=2,format=yuv420p[v]`, '-map', '[v]', '-map', '2:a',
      ...libx264(18), '-c:a', 'aac', '-b:a', '96k', '-ac', '2', ...ENC, out]);
  } },
  // 120 fps: 5 s x 300 frames; conformed to a 30 fps timeline it must drop exactly 3 of every 4 frames
  'edge-120fps': { file: 'edge-120fps.mp4', desc: '5 s 640x360@120 (300 frames, barcode), no audio', async build(out) {
    const s = strip({ w: 640, h: 360, fps: 120, dur: 5, cell: 20 });
    await ff([...s.v, '-filter_complex', `${s.base},format=yuv420p[v]`, '-map', '[v]', ...libx264(18, { preset: 'veryfast' }), '-an', ...ENC, out]);
  } },
  // 4K: 3840x2160 over the 1920 long-side cap; the conform must downscale to 1920x1080
  'edge-4k': { file: 'edge-4k.mp4', slow: true, desc: '4 s 3840x2160@25 4K (100 frames, barcode, crf 28), no audio', async build(out) {
    const s = strip({ w: 3840, h: 2160, fps: 25, dur: 4 });
    await ff([...s.v, '-filter_complex', `${s.base},format=yuv420p[v]`, '-map', '[v]', ...libx264(28, { preset: 'fast' }), '-an', ...ENC, out]);
  } },
  // 10-bit SDR (hlg already covers 10-bit HDR): yuv444p10le bt709 — media.json keeps the depth, conform lands 8-bit yuv420p
  'edge-10bit-sdr': { file: 'edge-10bit-sdr.mp4', desc: '6 s 1280x720@30 10-bit yuv444p10le bt709 SDR, 48 kHz stereo', async build(out) {
    const s = strip({ w: 1280, h: 720, fps: 30, dur: 6 });
    await ff([...s.v, '-f', 'lavfi', '-i', BEEP(6, 48000), '-filter_complex', `${s.base},format=yuv444p10le[v]`, '-map', '[v]', '-map', '2:a',
      ...libx264(18, { pix: 'yuv444p10le', extra: ['-colorspace', 'bt709', '-color_primaries', 'bt709', '-color_trc', 'bt709', '-color_range', 'tv'] }),
      '-c:a', 'aac', '-b:a', '96k', '-ac', '2', ...ENC, out]);
  } },
  // interlaced: 60p woven to 480i (tt) with real field coding (ilme+ildct, tff); the barcode is burned AFTER the
  // weave so both fields of a frame carry the same value and yadif can reconstruct it frame-exactly
  'edge-interlaced': { file: 'edge-interlaced.mp4', desc: '8 s 720x480i tt (60p woven via tinterlace, ilme+ildct), 48 kHz stereo', async build(out) {
    await ff(['-f', 'lavfi', '-i', 'testsrc2=s=720x480:r=60:d=8', '-f', 'lavfi', '-i', barcodeSource(30, 8), '-f', 'lavfi', '-i', BEEP(8, 48000),
      '-filter_complex', '[0:v]tinterlace=mode=interleave_top[t];[t][1:v]overlay=0:0,format=yuv420p[v]', '-map', '[v]', '-map', '2:a',
      '-r', '30', ...libx264(18, { extra: ['-flags', '+ilme+ildct', '-x264-params', 'tff=1'] }), '-c:a', 'aac', '-b:a', '96k', '-ac', '2', ...ENC, out]);
  } },
  // mono: 1 channel all the way in; ingest keeps it mono (audio.wav is 1ch), the dialog bus duplicates it L=R
  'edge-mono': { file: 'edge-mono.mp4', desc: '6 s 1280x720@30 with MONO 48 kHz audio', async build(out) {
    const s = strip({ w: 1280, h: 720, fps: 30, dur: 6 });
    await ff([...s.v, '-f', 'lavfi', '-i', BEEP(6, 48000), '-filter_complex', `${s.base},format=yuv420p[v]`, '-map', '[v]', '-map', '2:a',
      ...libx264(18), '-c:a', 'aac', '-b:a', '96k', '-ac', '1', ...ENC, out]);
  } },
  // 5.1: six distinct sines mapped to a 5.1 layout; ingest downmixes to stereo and records the layout
  'edge-51': { file: 'edge-51.mp4', desc: '6 s 1280x720@30 + 5.1 audio (6 sines, one per channel), 48 kHz', async build(out) {
    const s = strip({ w: 1280, h: 720, fps: 30, dur: 6 });
    await ff([...s.v, '-f', 'lavfi', '-i', `aevalsrc=exprs='${SINES_51}':s=48000:d=6`,
      '-filter_complex', `${s.base},format=yuv420p[v];[2:a]aformat=channel_layouts=5.1[a]`, '-map', '[v]', '-map', '[a]',
      ...libx264(18), '-c:a', 'aac', '-b:a', '320k', ...ENC, out]);
  } },
  // two audio streams: a quiet 300 Hz and a loud 900 Hz — --audio-stream 1 must pick the loud one, measurably
  'edge-2audio': { file: 'edge-2audio.mp4', desc: '6 s 1280x720@30 with TWO audio streams: 300 Hz at 0.04 and 900 Hz at 0.6 (48 kHz mono each)', async build(out) {
    const s = strip({ w: 1280, h: 720, fps: 30, dur: 6 });
    await ff([...s.v, '-f', 'lavfi', '-i', 'sine=f=300:r=48000:d=6', '-f', 'lavfi', '-i', 'sine=f=900:r=48000:d=6',
      '-filter_complex', `${s.base},format=yuv420p[v];[2:a]volume=0.04[a0];[3:a]volume=0.6[a1]`, '-map', '[v]', '-map', '[a0]', '-map', '[a1]',
      ...libx264(18), '-c:a', 'aac', '-b:a', '96k', ...ENC, out]);
  } },
  // non-zero start_time: mpegts with copyts and +1.5 s output offset — ffprobe reads start_time ~1.5 (audio ~1.479)
  'edge-start-offset': { file: 'edge-start-offset.ts', desc: '8 s 1280x720@30 mpegts with start_time 1.5 s (copyts + output_ts_offset), 48 kHz stereo', async build(out) {
    const s = strip({ w: 1280, h: 720, fps: 30, dur: 8 });
    await ff([...s.v, '-f', 'lavfi', '-i', BEEP(8, 48000), '-filter_complex', `${s.base},format=yuv420p[v]`, '-map', '[v]', '-map', '2:a',
      ...libx264(18), '-c:a', 'aac', '-b:a', '96k', '-ac', '2', '-mpegts_copyts', '1', '-output_ts_offset', '1.5', ...ENC, '-f', 'mpegts', out]);
  } },
  // under 1 s: 18 frames. Must ingest, conform and split at its middle without "too close to an edge"
  'edge-sub1s': { file: 'edge-sub1s.mp4', desc: '0.6 s 640x360@30 (18 frames, barcode), 48 kHz stereo', async build(out) {
    const s = strip({ w: 640, h: 360, fps: 30, dur: 0.6, cell: 20 });
    await ff([...s.v, '-f', 'lavfi', '-i', BEEP(0.6, 48000), '-filter_complex', `${s.base},format=yuv420p[v]`, '-map', '[v]', '-map', '2:a',
      ...libx264(18), '-c:a', 'aac', '-b:a', '96k', '-ac', '2', ...ENC, out]);
  } },
  // a still image as a clip: single PNG (barcode 0); ingest freezes it for the default 5 still-seconds
  'edge-still': { file: 'edge-still.png', desc: '1280x720 PNG (barcode frame 0) — a still image as a clip source', async build(out) {
    const s = strip({ w: 1280, h: 720, fps: 30, dur: 0.1 });
    await ff([...s.v, '-filter_complex', `${s.base},format=rgb24[v]`, '-map', '[v]', '-frames:v', '1', '-update', '1', '-f', 'image2', ...ENC, out]);
  } },
  // container zoo: one 6 s master, re-muxed to .mov/.mkv/.mts (copy) and re-encoded to .webm (vp9+opus).
  // All four must ingest and conform to the same frame count and barcode sequence.
  'edge-containers': { file: 'edge-containers.mov', extra: ['edge-containers.mkv', 'edge-containers.webm', 'edge-containers.mts'],
    desc: '6 s 1280x720@30 master re-muxed to .mov/.mkv/.mts and re-encoded to .webm (vp9+opus)', async build(out, dir) {
      const s = strip({ w: 1280, h: 720, fps: 30, dur: 6 }), master = join(dir, '.edge-containers-master.mp4');
      await ff([...s.v, '-f', 'lavfi', '-i', BEEP(6, 48000), '-filter_complex', `${s.base},format=yuv420p[v]`, '-map', '[v]', '-map', '2:a',
        ...libx264(18), '-c:a', 'aac', '-b:a', '96k', '-ac', '2', ...ENC, master]);
      await ff(['-i', master, '-c', 'copy', ...ENC, out]);                                     // .mov
      await ff(['-i', master, '-c', 'copy', ...ENC, join(dir, 'edge-containers.mkv')]);          // .mkv
      await ff(['-i', master, '-c', 'copy', ...ENC, '-f', 'mpegts', join(dir, 'edge-containers.mts')]); // .mts
      await ff(['-i', master, '-c:v', 'libvpx-vp9', '-deadline', 'realtime', '-cpu-used', '5', '-crf', '32', '-threads', '1',
        '-c:a', 'libopus', '-b:a', '64k', ...ENC, '-f', 'webm', join(dir, 'edge-containers.webm')]);
      rmSync(master, { force: true });
    } },
  // the >2 h marathon, represented by 25 minutes (a true 2 h PCM wav alone is 6.9 GB / an mp4 build is minutes):
  // enough to prove peaks/frame/sample arithmetic stays on safe integers (25 min = 72,000,000 samples < 2^31)
  'edge-25min': { file: 'edge-25min.mp4', slow: true, desc: '25 min 640x360@30 (45,000 frames, barcode, beep every 2 s) — stands in for >2 h sources', async build(out) {
    const s = strip({ w: 640, h: 360, fps: 30, dur: 1500, cell: 20 });
    await ff([...s.v, '-f', 'lavfi', '-i', BEEP(1500, 48000), '-filter_complex', `${s.base},format=yuv420p[v]`, '-map', '[v]', '-map', '2:a',
      ...libx264(30, { preset: 'veryfast', extra: ['-g', '300'] }), '-c:a', 'aac', '-b:a', '96k', '-ac', '2', ...ENC, out]);
  } },
};

const sha256 = (file) => new Promise((ok, bad) => { const h = createHash('sha256'); createReadStream(file).on('data', (d) => h.update(d)).on('end', () => ok(h.digest('hex'))).on('error', bad); });

export const edgeFixturePath = (id) => { const f = EDGE_FIXTURES[id]; if (!f) throw new Error(`unknown edge fixture "${id}"`); return join(EDGE_DIR, f.file); };

// Build what is missing (or everything with force). Returns the manifest entries touched. Mirrors ensureFixtures.
export async function ensureEdgeFixtures({ only, force = false, verify = false, includeSlow = true, log = console.log } = {}) {
  mkdirSync(EDGE_DIR, { recursive: true });
  const manifest = readJson(MANIFEST, { recipe: RECIPE, fixtures: {} });
  if (manifest.recipe !== RECIPE) { manifest.recipe = RECIPE; manifest.fixtures = {}; force = true; }
  const ids = (only ? only : Object.keys(EDGE_FIXTURES)).filter((id) => EDGE_FIXTURES[id] && (includeSlow || !EDGE_FIXTURES[id].slow));
  const touched = {};
  for (const id of ids) {
    const f = EDGE_FIXTURES[id], out = join(EDGE_DIR, f.file), have = manifest.fixtures[id];
    const extras = f.extra || [];
    const ok = !force && have && existsSync(out) && extras.every((x) => existsSync(join(EDGE_DIR, x))) && statSync(out).size === have.bytes && (!verify || (await sha256(out)) === have.sha256);
    if (ok) { touched[id] = { ...have, cached: true }; continue; }
    const t0 = Date.now();
    if (existsSync(out)) rmSync(out, { force: true });
    log(`edge fixture ${id}: building (${f.desc})`);
    await f.build(out, EDGE_DIR);
    manifest.fixtures[id] = { file: f.file, ...(f.extra ? { extra: f.extra } : {}), bytes: statSync(out).size, sha256: await sha256(out), desc: f.desc, built_at: new Date().toISOString(), seconds: +((Date.now() - t0) / 1000).toFixed(1) };
    touched[id] = manifest.fixtures[id];
    writeJson(MANIFEST, manifest);
  }
  writeJson(MANIFEST, manifest);
  return touched;
}

export const readEdgeManifest = () => readJson(MANIFEST, { recipe: RECIPE, fixtures: {} });
